// -- validation ---------------------------------------------------------------

/** One structural contract issue: which field, a stable code, and why. */
export interface PerfIssue {
  readonly field: string
  readonly code: PerfIssueCode
  readonly message: string
}

/** The stable validation codes a workload/budget rejection carries. */
export type PerfIssueCode =
  | 'workload-required'
  | 'workload-bounds'
  | 'budgets-required'
  | 'budgets-bounds'
  | 'segment-unknown'
  | 'label-key-unknown'
  | 'label-value-bound'
  | 'outcome-unknown'

/**
 * Validate one raw workload value (the frozen-input contract).
 * @param workload - the raw workload value.
 * @returns the issue list; empty means the workload may run.
 */
export function validatePerfWorkload(workload: unknown): PerfIssue[] {
  const issues: PerfIssue[] = []
  if (typeof workload !== 'object' || workload === null) {
    return [{ field: 'workload', code: 'workload-required', message: 'the workload must be an object' }]
  }
  const record = workload as Partial<PerfWorkload>
  intBound(issues, 'seed', record.seed, 0, 2 ** 31 - 1, 'workload-bounds')
  intBound(issues, 'repetitions', record.repetitions, 1, PERF_WORKLOAD_BOUNDS.maxRepetitions, 'workload-bounds')
  intBound(issues, 'locateLayerCount', record.locateLayerCount, 1, PERF_WORKLOAD_BOUNDS.maxLocateLayerCount, 'workload-bounds')
  intBound(issues, 'locateLayerFeatures', record.locateLayerFeatures, 1, PERF_WORKLOAD_BOUNDS.maxLayerFeatures, 'workload-bounds')
  intBound(issues, 'parseFeatureCount', record.parseFeatureCount, 1, PERF_WORKLOAD_BOUNDS.maxParseFeatureCount, 'workload-bounds')
  intBound(issues, 'spatialOpRepeats', record.spatialOpRepeats, 1, PERF_WORKLOAD_BOUNDS.maxSpatialOpRepeats, 'workload-bounds')
  intBound(issues, 'recoveryMutations', record.recoveryMutations, 1, PERF_WORKLOAD_BOUNDS.maxRecoveryMutations, 'workload-bounds')
  return issues
}

/**
 * Validate one raw budgets value.
 * @param budgets - the raw budgets value.
 * @returns the issue list; empty means the budgets may run.
 */
export function validatePerfBudgets(budgets: unknown): PerfIssue[] {
  const issues: PerfIssue[] = []
  if (typeof budgets !== 'object' || budgets === null) {
    return [{ field: 'budgets', code: 'budgets-required', message: 'the budgets must be an object' }]
  }
  const record = budgets as Partial<PerfHardBudgets>
  byteBound(issues, 'maxSessionBytes', record.maxSessionBytes)
  byteBound(issues, 'maxMetaBytes', record.maxMetaBytes)
  byteBound(issues, 'maxProjectionBytes', record.maxProjectionBytes)
  byteBound(issues, 'maxDisplayBytes', record.maxDisplayBytes)
  intBound(issues, 'maxScanRows', record.maxScanRows, PERF_BUDGET_BOUNDS.minScanRows, PERF_BUDGET_BOUNDS.maxScanRows, 'budgets-bounds')
  intBound(issues, 'maxTimeMs', record.maxTimeMs, PERF_BUDGET_BOUNDS.minTimeMs, PERF_BUDGET_BOUNDS.maxTimeMs, 'budgets-bounds')
  intBound(issues, 'maxConcurrency', record.maxConcurrency, PERF_BUDGET_BOUNDS.minConcurrency, PERF_BUDGET_BOUNDS.maxConcurrency, 'budgets-bounds')
  intBound(issues, 'maxSteps', record.maxSteps, PERF_BUDGET_BOUNDS.minSteps, PERF_BUDGET_BOUNDS.maxSteps, 'budgets-bounds')
  return issues
}

/** Validate one byte-carrying budget field. */
function byteBound(issues: PerfIssue[], field: string, value: unknown): void {
  intBound(issues, field, value, PERF_BUDGET_BOUNDS.minBytes, PERF_BUDGET_BOUNDS.maxBytes, 'budgets-bounds')
}

/** Validate one numeric integer field against an inclusive bound, recording one issue per violation. */
function intBound(issues: PerfIssue[], field: string, value: unknown, min: number, max: number, code: PerfIssueCode): void {
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    issues.push({ field, code, message: `${field} must be an integer in [${min}, ${max}]` })
  }
}

/**
 * The canonical digest of one plain-JSON value — the identity a report or
 * baseline pins.
 * @param value - the value to digest.
 * @returns a sha256 hex digest of the canonical JSON form.
 */
export function perfDigestOf(value: unknown): string {
  return createHash('sha256').update(JSON.stringify(value) ?? 'null', 'utf8').digest('hex')
}

/** Render one issue list the way every refusal message names its reasons. */
export function renderPerfIssues(issues: readonly PerfIssue[]): string {
  return issues.map(issue => `${issue.field} (${issue.code})`).join('; ')
}
